import { useRef, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "blue" | "emerald" | "amber" | "rose";

interface AccentOption {
  readonly id: Accent;
  readonly label: string;
}

const ACCENT_OPTIONS: readonly AccentOption[] = [
  { id: "blue", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (value: Accent) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const buttonRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const count = ACCENT_OPTIONS.length;

  // Roving tabindex: the selected option is the single tab stop.
  // If the value is somehow unknown, fall back to the first option.
  const selectedIndex = Math.max(
    0,
    ACCENT_OPTIONS.findIndex((option) => option.id === value),
  );

  const selectByIndex = (index: number) => {
    const wrapped = ((index % count) + count) % count;
    const option = ACCENT_OPTIONS[wrapped];
    if (!option) {
      return;
    }
    onChange(option.id);
    buttonRefs.current[wrapped]?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        event.preventDefault();
        selectByIndex(index + 1);
        break;
      case "ArrowLeft":
      case "ArrowUp":
        event.preventDefault();
        selectByIndex(index - 1);
        break;
      case "Home":
        event.preventDefault();
        selectByIndex(0);
        break;
      case "End":
        event.preventDefault();
        selectByIndex(count - 1);
        break;
      default:
        break;
    }
  };

  return (
    <div
      className="accent-picker"
      role="radiogroup"
      aria-label="Accent colour"
    >
      {ACCENT_OPTIONS.map((option, index) => {
        const checked = index === selectedIndex;
        return (
          <button
            key={option.id}
            ref={(element) => {
              buttonRefs.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            className={`accent-picker__option accent-picker__option--${option.id}`}
            onClick={() => selectByIndex(index)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-picker__swatch" aria-hidden="true">
              <span className="accent-picker__check" />
            </span>
            <span className="accent-picker__label">{option.label}</span>
          </button>
        );
      })}
    </div>
  );
}
